/**
 * Audio Recording and Web Audio AnalyserNode utilities for Treads.
 * Supports cross-browser MediaRecorder with Opus compression,
 * Web Audio frequency analysis, and Web Speech API fallback.
 */

export interface AudioAnalyserSetup {
  audioContext: AudioContext;
  analyser: AnalyserNode;
  source: MediaStreamAudioSourceNode;
  frequencyData: Uint8Array;
}

export function createAudioContext(): AudioContext {
  const AudioContextClass =
    window.AudioContext ||
    (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;

  const ctx = new AudioContextClass();
  if (ctx.state === 'suspended') {
    ctx.resume().catch((err) => {
      console.warn('Failed to resume AudioContext:', err);
    });
  }
  return ctx;
}

export function setupAudioAnalyser(
  stream: MediaStream,
  audioContext: AudioContext
): AudioAnalyserSetup {
  const analyser = audioContext.createAnalyser();
  analyser.fftSize = 64; // Yields 32 frequency bins
  analyser.smoothingTimeConstant = 0.8;

  const source = audioContext.createMediaStreamSource(stream);
  source.connect(analyser);

  const frequencyData = new Uint8Array(analyser.frequencyBinCount);
  return { audioContext, analyser, source, frequencyData };
}

export function getPreferredAudioMimeType(): string {
  if (typeof MediaRecorder === 'undefined') {
    return 'audio/webm';
  }

  const candidateTypes = [
    'audio/webm;codecs=opus',
    'audio/webm',
    'audio/mp4',
    'audio/aac',
    'audio/ogg;codecs=opus',
  ];

  for (const type of candidateTypes) {
    if (MediaRecorder.isTypeSupported(type)) {
      return type;
    }
  }

  return '';
}

export function startMediaRecorder(stream: MediaStream): MediaRecorder {
  const mimeType = getPreferredAudioMimeType();
  const options: MediaRecorderOptions = mimeType ? { mimeType } : {};
  return new MediaRecorder(stream, options);
}

export function stopMediaStream(stream: MediaStream | null | undefined): void {
  if (!stream) return;
  try {
    const tracks = stream.getTracks();
    for (const track of tracks) {
      track.stop();
    }
  } catch (err) {
    console.warn('Error stopping media tracks:', err);
  }
}

export interface WebSpeechResult {
  transcript: string;
  isFinal: boolean;
  confidence?: number;
}

export class BrowserSpeechRecognitionSession {
  private recognition: any = null;
  private isListening = false;

  constructor(
    private onResult: (res: WebSpeechResult) => void,
    private onError: (err: any) => void
  ) {
    if (typeof window === 'undefined') return;

    const SpeechRecognition =
      (window as any).SpeechRecognition ||
      (window as any).webkitSpeechRecognition;

    if (SpeechRecognition) {
      this.recognition = new SpeechRecognition();
      this.recognition.continuous = true;
      this.recognition.interimResults = true;
      this.recognition.lang = 'en-US';

      this.recognition.onresult = (event: any) => {
        let interimTranscript = '';
        let finalTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; ++i) {
          const item = event.results[i];
          if (item.isFinal) {
            finalTranscript += item[0].transcript;
          } else {
            interimTranscript += item[0].transcript;
          }
        }

        const text = finalTranscript || interimTranscript;
        if (text) {
          this.onResult({
            transcript: text.trim(),
            isFinal: Boolean(finalTranscript),
            confidence: event.results[0]?.[0]?.confidence,
          });
        }
      };

      this.recognition.onerror = (err: any) => {
        this.onError(err);
      };
    }
  }

  public isAvailable(): boolean {
    return Boolean(this.recognition);
  }

  public start(): void {
    if (this.recognition && !this.isListening) {
      try {
        this.recognition.start();
        this.isListening = true;
      } catch (err) {
        console.warn('SpeechRecognition start error:', err);
      }
    }
  }

  public stop(): void {
    if (this.recognition && this.isListening) {
      try {
        this.recognition.stop();
      } catch (err) {
        console.warn('SpeechRecognition stop error:', err);
      } finally {
        this.isListening = false;
      }
    }
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { checkRateLimit } from '@/lib/rate-limit';

export async function POST(req: NextRequest) {
  // 1. Rate limiting check
  const rateLimit = await checkRateLimit(req, 'transcribe');
  if (!rateLimit.success) {
    return NextResponse.json(
      { error: 'Rate limit exceeded for transcription. Try again later.' },
      { status: 429, headers: rateLimit.headers }
    );
  }

  try {
    let audioBlob: Blob | null = null;
    let languageHint: string = 'en';

    const contentType = req.headers.get('content-type') || '';
    if (contentType.includes('multipart/form-data')) {
      const formData = await req.formData();
      const fileEntry = formData.get('file');
      if (fileEntry instanceof Blob) {
        audioBlob = fileEntry;
      }
      const lang = formData.get('language');
      if (typeof lang === 'string') {
        languageHint = lang;
      }
    } else if (contentType.includes('application/json')) {
      const json = await req.json();
      if (json.audioBase64) {
        const buffer = Buffer.from(json.audioBase64, 'base64');
        audioBlob = new Blob([buffer], { type: json.mimeType || 'audio/webm' });
      }
      if (json.language) {
        languageHint = json.language;
      }
    }

    if (!audioBlob) {
      return NextResponse.json(
        { error: 'No audio file provided' },
        { status: 400, headers: rateLimit.headers }
      );
    }

    const apiKey = process.env.ELEVENLABS_API_KEY;

    // 2. Call ElevenLabs Scribe STT if API key is configured
    if (apiKey) {
      const elevenFormData = new FormData();
      elevenFormData.append('file', audioBlob, 'audio.webm');
      elevenFormData.append('model_id', 'scribe_v1');
      if (languageHint) {
        elevenFormData.append('language_code', languageHint);
      }

      const res = await fetch('https://api.elevenlabs.io/v1/speech-to-text', {
        method: 'POST',
        headers: {
          'xi-api-key': apiKey,
        },
        body: elevenFormData,
      });

      if (res.ok) {
        const data = await res.json();
        return NextResponse.json(
          {
            transcript: data.text || '',
            language: data.language_code || languageHint || 'en',
            fallback: false,
          },
          { status: 200, headers: rateLimit.headers }
        );
      } else {
        console.warn(
          'ElevenLabs STT API error status:',
          res.status,
          await res.text()
        );
      }
    }

    // 3. Graceful fallback when key is absent or API returned error
    return NextResponse.json(
      {
        transcript: 'Observed organism in natural habitat during field walk.',
        language: languageHint || 'en',
        fallback: true,
        warning:
          'ELEVENLABS_API_KEY not configured or unreachable. Falling back to default transcript.',
      },
      { status: 200, headers: rateLimit.headers }
    );
  } catch (err: any) {
    console.error('Transcription route error:', err);
    return NextResponse.json(
      { error: err.message || 'Internal transcription error' },
      { status: 500, headers: rateLimit.headers }
    );
  }
}

